const { mkdtempSync, rmSync } = await import("fs");
const { tmpdir } = await import("os");
const { join } = await import("path");
const { pathToFileURL } = await import("url");
const root = mkdtempSync(join(tmpdir(), "koala-phase-"));
const { StoryStore } = await import(pathToFileURL($root + "/packages/main/dist/core/store.js").href);
const store = new StoryStore(root);
const storyId = "B-test";
store.writeStory(storyId, { storyId, name: "phase", title: "Phase", description: "fixture", type: "bug", priority: "low", phase: "DEV", events: [] });
store.writeChecklist(storyId, { items: [{ id: "CHK-001", title: "impl", context: "ctx", status: "pending", startTime: null, endTime: null, testIntent: { happy: [{ desc: "happy", type: "cli_blackbox" }], edge: [], adversarial: [] } }] });
try {
  const { createChecklistHandlers } = await import(pathToFileURL($root + "/packages/main/dist/handlers/checklist.js").href);
  const handlers = createChecklistHandlers({ root, store, scanRoot: root });
  const out = handlers.checklist_update({ storyId, itemId: "CHK-001", status: "done" });
  const read = store.readChecklist(storyId);
  return { ok: out.includes("status → done"), status: read.items[0].status };
} finally { rmSync(root, { recursive: true, force: true }); }

